/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/rendering_view_0025fcb8.c, FUN_L00_0025fcb8. */
int FindNearestTargetMoby(Moby *a, struct TargetLock *o, float best) {
    Hero *g = (Hero *)g_hero;
    char *m;
    Moby *p;
    int res;
    int i;
    int j;
    float d;

    m = *(char **)&g->moby;
    res = 0;
    if (g->state.control_mode == 0x18 || g->state.current == 0x72) {
        m = 0;
        res = 2;
    }
    for (i = 1; i <= decoy_list[0]; i++) {
        p = (Moby *)(moby_array_start_r + (decoy_list[i] << 8));
        if (p == 0) continue;
        if (p->oclass != 0xCB && p->oclass != 0x76C) continue;
        if (p->state == 0xFE) continue;
        if (p->state == 0xFD) continue;
        if (p->state != 3) continue;
        d = vec_distance_xy_r2(&a->pos, &p->pos);
        if (d < best) {
            m = (char *)p;
            best = d;
            res = 1;
        }
    }
    for (j = 0; j < 20; j++) {
        p = (Moby *)morphoray_chicken_slots[j];
        if (p == 0) continue;
        if (p->oclass != 0x10E) continue;
        if (p->state == 0xFE) continue;
        if (p->state == 0xFD) continue;
        if (p->command == 0) continue;
        d = vec_distance_xy_r2(&a->pos, &p->pos);
        if (d < best) {
            m = (char *)p;
            best = d;
            res = 1;
        }
    }
    if (m != 0) {
        *(char **)&o->moby = m;
        qcopy(&o->pos, m + 0x10);
        qcopy(&o->rot, m + 0x40);
        g = (Hero *)g_hero;
        if (m == *(char **)&g->moby) {
            qcopy(&o->aim, &g->motion.near_ground_point);
            qcopy(&o->aim_from, &g->motion.body_center);
        } else {
            qcopy(&o->aim_from, (char *)o);
            o->aim_from.f[2] += 0.6f;
            qcopy(&o->aim, &o->aim_from);
        }
    } else {
        *(char **)&o->moby = 0;
        qzero(&o->pos);
        qzero(&o->rot);
        qzero(&o->aim_from);
        qzero(&o->aim);
    }
    o->result = res;
    return res;
}
