/* Picks the nearest eligible moby to A within BEST that passes the id list or the volume test, fills the record O and returns 0, 1 or 2. */
int FindNearestEligibleMoby(Moby *a, struct TargetLock *o, float best, int *list, int n, float *v, int nv) {
    Hero *g = (Hero *)g_hero;
    char *m;
    Moby *p;
    Moby *q;
    int res;
    int i;
    int j;
    int k;
    int ok;
    float d;

    m = *(char **)&g->moby;
    res = 0;
    if (g->state.control_mode == 0x18 || g->state.current == 0x72) {
        m = 0;
        res = 2;
    } else if (n > 0) {
        for (k = 0; k < n - 1; k++) {
            if (is_point_inside_clip_volume_r(g_hero + 0x80, list[k]) != 0) {
                m = 0;
                res = 2;
                break;
            }
        }
    } else if (v != 0 && nv > 0) {
        if (IsPointInPolygon_r(g_hero + 0x80, v, nv) == 0) {
            m = 0;
            res = 2;
        }
    }
    for (i = 1; i <= decoy_list[0]; i++) {
        p = (Moby *)(moby_array_start_r + (decoy_list[i] << 8));
        if (p == 0) continue;
        if (p->oclass != 0xCB && p->oclass != 0x76C) continue;
        if (p->state == 0xFE) continue;
        if (p->state == 0xFD) continue;
        if (p->state != 3) continue;
        ok = 1;
        d = vec_distance_xy_r2(&a->pos, &p->pos);
        if (best <= d) {
            ok = 0;
        } else if (n > 0) {
            for (k = 0; k < n - 1; k++) {
                if (is_point_inside_clip_volume_r(&p->pos, list[k]) != 0) {
                    ok = 0;
                    break;
                }
            }
        } else if (v != 0 && nv > 0) {
            if (IsPointInPolygon_r(&p->pos, v, nv) == 0) ok = 0;
        }
        if (ok) {
            m = (char *)p;
            res = 1;
            best = d;
        }
    }
    for (j = 0; j < 20; j++) {
        q = (Moby *)morphoray_chicken_slots[j];
        if (q == 0) continue;
        if (q->oclass != 0x10E) continue;
        if (q->state == 0xFE) continue;
        if (q->state == 0xFD) continue;
        if (q->command == 0) continue;
        ok = 1;
        d = vec_distance_xy_r2(&a->pos, &q->pos);
        if (best <= d) {
            ok = 0;
        } else if (n > 0) {
            for (k = 0; k < n - 1; k++) {
                if (is_point_inside_clip_volume_r(&q->pos, list[k]) != 0) {
                    ok = 0;
                    break;
                }
            }
        } else if (v != 0 && nv > 0) {
            if (IsPointInPolygon_r(&q->pos, v, nv) == 0) ok = 0;
        }
        if (ok) {
            m = (char *)q;
            res = 1;
            best = d;
        }
    }
    if (m != 0) {
        *(char **)&o->moby = m;
        qcopy(&o->pos, m + 0x10);
        qcopy(&o->rot, m + 0x40);
        g = (Hero *)g_hero;
        if (m == *(char **)&g->moby) {
            qcopy(&o->aim, &g->motion.near_ground_point);
            qcopy(&o->aim_from, &g->motion.body_center);
        } else {
            qcopy(&o->aim_from, (char *)o);
            o->aim_from.f[2] += 0.6f;
            qcopy(&o->aim, &o->aim_from);
        }
    } else {
        *(char **)&o->moby = 0;
        qzero(&o->pos);
        qzero(&o->rot);
        qzero(&o->aim_from);
        qzero(&o->aim);
    }
    o->result = res;
    return res;
}
